  "canonical_text": {
    "quote": "",
    "summary": "A lyric defines fortune as seeing Beauty, asking alms in her lane, and disdaining royal pomp. It reflects on loosening attachment to life, the pain of losing friends, wandering to an orchard, casting off reputation, hearing secrets of Love from wind, flower, and bulbuls, seizing the occasion to kiss the Beloved, valuing companionship before an irreversible departure from a two-doored house, and asking the Lord to remind Hafiz of Shah Mansur and the poor.",
    "language": "English",
    "quote_policy": "summarized"
  },
  "literal_observations": [
    {
      "id": "obs:1",
      "text": "Fortune is described as obtaining the sight of Beauty, asking for alms in her lane, and disdaining royal pomp.",
      "category": "attribute",
      "evidence_refs": [
        "ev:1"
      ]
    },
    {
      "id": "obs:2",
      "text": "Severance from the wish for life is called easy, while losing friends who sweeten life is called hard.",
      "category": "relationship",
      "evidence_refs": [
        "ev:2"
      ]
    },
    {
      "id": "obs:3",
      "text": "The speaker says he will go to the orchard bud-like with a serried heart and tear the garment of his good repute to pieces there.",
      "category": "action",
      "evidence_refs": [
        "ev:3"
      ]
    },
    {
      "id": "obs:4",
      "text": "The West-wind is invoked as one that tells deep secrets to the Flower.",
      "category": "action",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:5",
      "text": "The listener is told to hear of Love's mysterious sport from bulbuls of the bower.",
      "category": "speech",
      "evidence_refs": [
        "ev:4"
      ]
    },
    {
      "id": "obs:6",
      "text": "The listener is urged to kiss the Beloved one's lips while the occasion remains.",
      "category": "action",
      "evidence_refs": [
        "ev:5"
      ]
    },
    {
      "id": "obs:7",
      "text": "The passage urges profit from companionship because, once the two-doored house is forsaken, no pathway later leads back to it.",
      "category": "sequence",
      "evidence_refs": [
        "ev:6"
      ]
    },
    {
      "id": "obs:8",
      "text": "Hafiz is said to have fleeted from the thought of Shah Mansur, and the Lord is asked to remind him that the poor should be treated with favor.",
      "category": "speech",
      "evidence_refs": [
        "ev:7"
      ]
    }
